#!/usr/bin/env python3
"""Update a small HWPX (zip) document by editing section XML files.

- Updates field values using renewal_update.json
- Replaces follow-up paragraphs using followups.csv (sorted by sequence)
- Removes <*linesegarray> elements from any paragraph whose text was modified
- Preserves appendix sentence exactly: "이 부록 문단은 그대로 유지해야 합니다."

Outputs: /root/renewal_playbook_updated.hwpx
"""

from __future__ import annotations

import csv
import copy
import json
import os
import re
import shutil
import sys
import tempfile
import zipfile
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

import xml.etree.ElementTree as ET


HWPX_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HWPX_NS}
ET.register_namespace("hp", HWPX_NS)

APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."


@dataclass
class UpdateData:
    customer: str
    owner_name: str
    window_start: str
    window_end: str
    band: str
    escalation_email: str
    note: str


def read_update_data(json_path: str) -> UpdateData:
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    return UpdateData(
        customer=data["customer"],
        owner_name=data["owner_name"],
        window_start=data["window_start"],
        window_end=data["window_end"],
        band=data["band"],
        escalation_email=data["escalation_email"],
        note=data["note"],
    )


def read_followups(csv_path: str) -> List[Tuple[int, str]]:
    items: List[Tuple[int, str]] = []
    with open(csv_path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            seq = int(row["sequence"].strip())
            item = row["item"].strip()
            items.append((seq, item))
    items.sort(key=lambda x: x[0])
    return items


def local_name(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def paragraph_text(p: ET.Element) -> str:
    # Concatenate all hp:t texts in document order.
    texts: List[str] = []
    for t in p.findall(".//hp:t", NS):
        if t.text:
            texts.append(t.text)
    return "".join(texts)


def set_paragraph_text(p: ET.Element, new_text: str) -> None:
    ts = p.findall(".//hp:t", NS)
    if not ts:
        run = ET.SubElement(p, f"{{{HWPX_NS}}}run")
        t = ET.SubElement(run, f"{{{HWPX_NS}}}t")
        t.text = new_text
        return

    ts[0].text = new_text
    for t in ts[1:]:
        t.text = ""


def remove_linesegarray_children(p: ET.Element) -> int:
    # Remove any descendants whose local-name() == linesegarray.
    removed = 0
    for parent in list(p.iter()):
        for child in list(parent):
            if local_name(child.tag) == "linesegarray":
                parent.remove(child)
                removed += 1
    return removed


def next_paragraph_id(section: ET.Element) -> int:
    max_id = -1
    for p in section.findall(".//hp:p", NS):
        pid = p.get("id")
        if pid is None:
            continue
        try:
            max_id = max(max_id, int(pid))
        except ValueError:
            continue
    return max_id + 1


def find_followup_paragraphs(section: ET.Element) -> List[ET.Element]:
    """Return contiguous numbered follow-up paragraphs (e.g., '1. ...', '2. ...')."""
    ps = section.findall("./hp:p", NS)
    numbered: List[ET.Element] = []

    num_re = re.compile(r"^\s*(\d+)\.\s*")

    # Find first numbered paragraph.
    start_idx: Optional[int] = None
    for i, p in enumerate(ps):
        txt = paragraph_text(p)
        if txt == APPENDIX_SENTENCE:
            continue
        if num_re.match(txt):
            start_idx = i
            break

    if start_idx is None:
        return []

    # Collect contiguous numbered paragraphs from start.
    for p in ps[start_idx:]:
        txt = paragraph_text(p)
        if num_re.match(txt):
            numbered.append(p)
        else:
            break

    return numbered


def apply_updates_to_section(tree: ET.ElementTree, update: UpdateData, followups: List[Tuple[int, str]]) -> Dict[str, int]:
    root = tree.getroot()

    modified_paragraphs: List[ET.Element] = []

    # Targeted paragraph updates by prefix.
    for p in root.findall(".//hp:p", NS):
        txt = paragraph_text(p)
        if not txt:
            continue
        if txt == APPENDIX_SENTENCE:
            continue

        new_txt: Optional[str] = None

        if txt.startswith("고객사:"):
            new_txt = f"고객사: {update.customer}"
        elif txt.startswith("현 담당자:"):
            new_txt = f"현 담당자: {update.owner_name}"
        elif txt.startswith("갱신 윈도우:"):
            new_txt = f"갱신 윈도우: {update.window_start} ~ {update.window_end}"
        elif txt.startswith("갱신 윈도우 확인:"):
            new_txt = f"갱신 윈도우 확인: {update.window_start} ~ {update.window_end}"
        elif txt.startswith("가격 메모:"):
            new_txt = f"가격 메모: {update.note}"
        else:
            # Table values and any other places: do exact-value replacements.
            if txt.strip() == "Standard-18M":
                new_txt = update.band
            elif txt.strip() == "ops-old@northwind.example":
                new_txt = update.escalation_email

        if new_txt is not None and new_txt != txt:
            set_paragraph_text(p, new_txt)
            modified_paragraphs.append(p)

    # Follow-up paragraphs replacement (if this section has them).
    followup_ps = find_followup_paragraphs(root)
    if followup_ps:
        # Build desired follow-up texts; keep numbering aligned with sequence order.
        desired = [f"{seq}. {item}" for seq, item in followups]

        existing = followup_ps
        parent = root  # in this sample, section's direct children are hp:p

        if len(existing) == len(desired):
            for p, new_txt in zip(existing, desired):
                old = paragraph_text(p)
                if old != new_txt:
                    set_paragraph_text(p, new_txt)
                    modified_paragraphs.append(p)
        elif len(existing) > len(desired):
            # Update first N, remove the rest.
            for p, new_txt in zip(existing[: len(desired)], desired):
                old = paragraph_text(p)
                if old != new_txt:
                    set_paragraph_text(p, new_txt)
                    modified_paragraphs.append(p)
            for p in existing[len(desired) :]:
                # Remove paragraph element entirely.
                try:
                    parent.remove(p)
                except ValueError:
                    pass
        else:
            # Need to add paragraphs: update existing then clone last.
            for p, new_txt in zip(existing, desired[: len(existing)]):
                old = paragraph_text(p)
                if old != new_txt:
                    set_paragraph_text(p, new_txt)
                    modified_paragraphs.append(p)

            # Clone the last existing paragraph as template.
            template = existing[-1]
            insert_after = template

            next_id = next_paragraph_id(root)
            for new_txt in desired[len(existing) :]:
                clone = copy.deepcopy(template)
                clone.set("id", str(next_id))
                next_id += 1
                set_paragraph_text(clone, new_txt)
                modified_paragraphs.append(clone)

                # Insert clone right after insert_after among direct children.
                children = list(parent)
                try:
                    idx = children.index(insert_after)
                except ValueError:
                    parent.append(clone)
                else:
                    parent.insert(idx + 1, clone)
                insert_after = clone

    # Remove linesegarray for every modified paragraph.
    removed_linesegarrays = 0
    for p in modified_paragraphs:
        removed_linesegarrays += remove_linesegarray_children(p)

    # Ensure appendix sentence exists unchanged.
    appendix_ok = any(paragraph_text(p) == APPENDIX_SENTENCE for p in root.findall(".//hp:p", NS))
    if not appendix_ok:
        raise RuntimeError("Appendix sentence missing or modified")

    return {
        "modified_paragraphs": len(modified_paragraphs),
        "removed_linesegarrays": removed_linesegarrays,
    }


def extract_zip(src_hwpx: str, dest_dir: str) -> None:
    with zipfile.ZipFile(src_hwpx, "r") as z:
        z.extractall(dest_dir)


def rezip_hwpx(src_dir: str, dest_hwpx: str) -> None:
    # Write a zip with stable ordering; if there's a mimetype file, store it first with no compression.
    all_paths: List[str] = []
    for root, dirs, files in os.walk(src_dir):
        dirs.sort()
        files.sort()
        for fn in files:
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, src_dir)
            all_paths.append(rel)

    def write_file(zf: zipfile.ZipFile, rel: str, compression: int) -> None:
        full = os.path.join(src_dir, rel)
        zf.write(full, arcname=rel, compress_type=compression)

    with zipfile.ZipFile(dest_hwpx, "w") as zf:
        if "mimetype" in all_paths:
            write_file(zf, "mimetype", zipfile.ZIP_STORED)
            all_paths.remove("mimetype")
        for rel in all_paths:
            write_file(zf, rel, zipfile.ZIP_DEFLATED)


def main() -> int:
    src_hwpx = "/root/renewal_playbook.hwpx"
    json_path = "/root/renewal_update.json"
    csv_path = "/root/followups.csv"
    out_hwpx = "/root/renewal_playbook_updated.hwpx"

    update = read_update_data(json_path)
    followups = read_followups(csv_path)

    with tempfile.TemporaryDirectory(prefix="hwpx_edit_") as tmp:
        extracted = os.path.join(tmp, "extracted")
        os.makedirs(extracted, exist_ok=True)
        extract_zip(src_hwpx, extracted)

        # Update all section XMLs under Contents/
        contents_dir = os.path.join(extracted, "Contents")
        stats = {}
        for fn in os.listdir(contents_dir):
            if not fn.lower().endswith(".xml"):
                continue
            path = os.path.join(contents_dir, fn)
            tree = ET.parse(path)
            file_stats = apply_updates_to_section(tree, update, followups)
            stats[fn] = file_stats
            tree.write(path, encoding="UTF-8", xml_declaration=True)

        rezip_hwpx(extracted, out_hwpx)

    # Print a short summary for logs.
    print("Wrote", out_hwpx)
    print(json.dumps(stats, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

