            # Table values and any other places: do exact-value replacements.
            if txt.strip() == "Standard-18M":
                new_txt = update.band
            elif txt.strip() == "ops-old@northwind.example":
                new_txt = update.escalation_email

        if new_txt is not None and new_txt != txt:
            set_paragraph_text(p, new_txt)
            modified_paragraphs.append(p)

    # Follow-up paragraphs replacement (if this section has them).
    followup_ps = find_followup_paragraphs(root)
    if followup_ps:
        # Build desired follow-up texts; keep numbering aligned with sequence order.
        desired = [f"{seq}. {item}" for seq, item in followups]

        existing = followup_ps
        parent = root  # in this sample, section's direct children are hp:p

        if len(existing) == len(desired):
            for p, new_txt in zip(existing, desired):
                old = paragraph_text(p)
                if old != new_txt:
                    set_paragraph_text(p, new_txt)
                    modified_paragraphs.append(p)
        elif len(existing) > len(desired):
            # Update first N, remove the rest.
            for p, new_txt in zip(existing[: len(desired)], desired):
                old = paragraph_text(p)
                if old != new_txt:
                    set_paragraph_text(p, new_txt)
                    modified_paragraphs.append(p)
            for p in existing[len(desired) :]:
                # Remove paragraph element entirely.
                try:
                    parent.remove(p)
                except ValueError:
                    pass
        else:
            # Need to add paragraphs: update existing then clone last.
            for p, new_txt in zip(existing, desired[: len(existing)]):
                old = paragraph_text(p)
                if old != new_txt:
                    set_paragraph_text(p, new_txt)
                    modified_paragraphs.append(p)

            # Clone the last existing paragraph as template.
            template = existing[-1]
            insert_after = template

            next_id = next_paragraph_id(root)
            for new_txt in desired[len(existing) :]:
                clone = copy.deepcopy(template)
                clone.set("id", str(next_id))
                next_id += 1
                set_paragraph_text(clone, new_txt)
                modified_paragraphs.append(clone)

                # Insert clone right after insert_after among direct children.
                children = list(parent)
                try:
                    idx = children.index(insert_after)
                except ValueError:
                    parent.append(clone)
                else:
                    parent.insert(idx + 1, clone)
                insert_after = clone

    # Remove linesegarray for every modified paragraph.
    removed_linesegarrays = 0
    for p in modified_paragraphs:
        removed_linesegarrays += remove_linesegarray_children(p)

    # Ensure appendix sentence exists unchanged.
    appendix_ok = any(paragraph_text(p) == APPENDIX_SENTENCE for p in root.findall(".//hp:p", NS))
    if not appendix_ok:
        raise RuntimeError("Appendix sentence missing or modified")

    return {
        "modified_paragraphs": len(modified_paragraphs),
        "removed_linesegarrays": removed_linesegarrays,
    }


def extract_zip(src_hwpx: str, dest_dir: str) -> None:
    with zipfile.ZipFile(src_hwpx, "r") as z:
        z.extractall(dest_dir)


def rezip_hwpx(src_dir: str, dest_hwpx: str) -> None:
    # Write a zip with stable ordering; if there's a mimetype file, store it first with no compression.
    all_paths: List[str] = []
    for root, dirs, files in os.walk(src_dir):
        dirs.sort()
        files.sort()
        for fn in files:
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, src_dir)
            all_paths.append(rel)

    def write_file(zf: zipfile.ZipFile, rel: str, compression: int) -> None:
        full = os.path.join(src_dir, rel)
        zf.write(full, arcname=rel, compress_type=compression)

    with zipfile.ZipFile(dest_hwpx, "w") as zf:
        if "mimetype" in all_paths:
            write_file(zf, "mimetype", zipfile.ZIP_STORED)
            all_paths.remove("mimetype")
        for rel in all_paths:
            write_file(zf, rel, zipfile.ZIP_DEFLATED)


def main() -> int:
    src_hwpx = "/root/renewal_playbook.hwpx"
    json_path = "/root/renewal_update.json"
    csv_path = "/root/followups.csv"
    out_hwpx = "/root/renewal_playbook_updated.hwpx"

    update = read_update_data(json_path)
    followups = read_followups(csv_path)

    with tempfile.TemporaryDirectory(prefix="hwpx_edit_") as tmp:
        extracted = os.path.join(tmp, "extracted")
        os.makedirs(extracted, exist_ok=True)
        extract_zip(src_hwpx, extracted)

        # Update all section XMLs under Contents/
        contents_dir = os.path.join(extracted, "Contents")
        stats = {}
        for fn in os.listdir(contents_dir):
            if not fn.lower().endswith(".xml"):
                continue
            path = os.path.join(contents_dir, fn)
            tree = ET.parse(path)
            file_stats = apply_updates_to_section(tree, update, followups)
            stats[fn] = file_stats
            tree.write(path, encoding="UTF-8", xml_declaration=True)

        rezip_hwpx(extracted, out_hwpx)

    # Print a short summary for logs.
    print("Wrote", out_hwpx)
    print(json.dumps(stats, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

